 if(new URLSearchParams(location.search).has('service')){const url=new URL(location.href);url.searchParams.delete('service');history.replaceState(history.state,'',url);}
 currentNav('services-nav');workspaceState=state??workspaceState;serviceEditor=null;editorDirty=false;form('Services').remove();
 const title=el('div');title.className='services-title';const copy=el('div');copy.append(el('h1','Services'));copy.append(el('p','Manage what your MCP clients can connect to.'));title.append(copy);content.append(title);
