 f.onsubmit=async e=>{e.preventDefault();if(!validateFields(f))return;const u=listing.eligible.find(u=>u.id===select.value);if(!u)return;const b=f.querySelector('button');b.disabled=true;try{await api('service/mappings',{id,base:d.revision,generation:d.draft.generation,fingerprint:d.mappingFingerprint,mappings:[{subject:issue.subject,target:u.issuer?{issuer:u.issuer,externalSubject:u.externalSubject}:{localId:u.id}}]});selections.delete(issue.subject);await mappingRecovery(id,selections);banner.textContent='Mapping saved. Other draft edits are kept; no service was activated.';}catch(error){showError(error.message,error.operation);const recover=action(errors,'Refresh mapping status',async()=>{await mappingRecovery(id,selections);banner.textContent='Current saved mapping status loaded. Check remaining issues before choosing again.';});recover.focus();errors.append(el('p','Your configuration draft is retained. Inspect current saved mappings before retrying; a lost response does not mean the change failed.'));}};
